  const counts = INSTRUMENTS.map((_, t) => S.extra.filter(g => g.type === t).length);
  const type = counts.indexOf(Math.min(...counts));                      // spread guests across instruments
  S.extra.push({ type, cur, muted: false, pulse: 0, why: null, last: null });
