SP=/private/tmp/claude-501/-Users-gillian-kuo-project-storage-durhack/09aeef89-2562-4e89-80b3-a94b50614a99/scratchpad
cat > $SP/gtest/drive.mjs <<'EOF'
// Drives headless Chrome through the gallery: open → read cards → Replay → check the orchestra state.
import { spawn } from 'node:child_process';
const sp = process.argv[2];
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  ['--headless=new', '--remote-debugging-port=9333', `--user-data-dir=${sp}/chrome`, '--autoplay-policy=no-user-gesture-required', 'about:blank']);
const sleep = ms => new Promise(r => setTimeout(r, ms));
let tabs; for (let i = 0; i < 40 && !tabs; i++) { await sleep(250); tabs = await fetch('http://127.0.0.1:9333/json').then(r => r.json()).catch(() => null); }
const ws = new WebSocket(tabs.find(t => t.type === 'page').webSocketDebuggerUrl);
await new Promise(r => ws.onopen = r);
let id = 0; const wait = new Map();
ws.onmessage = m => { const d = JSON.parse(m.data); if (wait.has(d.id)) { wait.get(d.id)(d); wait.delete(d.id); } };
const send = (method, params = {}) => new Promise(r => { const i = ++id; wait.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
const js = async expr => { const r = await send('Runtime.evaluate', { expression: expr, awaitPromise: true, returnByValue: true, userGesture: true });
  if (r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails).slice(0, 400)); return r.result.result.value; };
const errors = [];
await send('Runtime.enable'); ws.addEventListener('message', m => { const d = JSON.parse(m.data); if (d.method === 'Runtime.exceptionThrown') errors.push(d.params.exceptionDetails.exception?.description || d.params.exceptionDetails.text); });
await send('Page.navigate', { url: 'http://localhost:5051/' });
for (let i = 0; i < 80; i++) { await sleep(250); if (await js('typeof S !== "undefined" && S.ready').catch(() => false)) break; }
await js('S.aiRetryAt = 1e15');                     // don't spend Gemini quota during the test
console.log('ready:', await js('S.ready'), '| currencies:', await js('S.names.length'));
await js("document.getElementById('galleryBtn').click()"); await sleep(1500);
console.log('note:', await js("document.getElementById('galleryNote').textContent"));
console.log('card:', await js("document.querySelector('.gitem')?.innerText"));
console.log('title escaped:', await js("document.querySelector('.gtitle').innerHTML"));
await js("document.querySelector('[data-replay]').click()"); await sleep(1200);
console.log(await js(`JSON.stringify({ hidden: document.getElementById('gallery').hidden, view: S.names[S.view], viewMenu: document.getElementById('viewFrom').value,
  date: S.dates[S.idx], playing: S.playing, voice: S.voice.map(t => INSTRUMENTS[t].label), assign: S.assign.map(c => S.names[c]),
  removed: S.removed, muted: S.muted, guests: S.extra.map(g => INSTRUMENTS[g.type].label + '→' + S.names[g.cur]),
  status: document.getElementById('status').textContent, seatRows: document.querySelectorAll('#seating .seat').length })`));
await sleep(3000);
console.log('still playing after 3 s:', await js('S.playing'), '| step:', await js('S.step'), '| errors:', errors.length ? errors : 'none');
const shot = await send('Page.captureScreenshot'); (await import('node:fs')).writeFileSync(`${sp}/shot.png`, Buffer.from(shot.result.data, 'base64'));
await js("document.getElementById('galleryBtn').click()"); await sleep(800);
const shot2 = await send('Page.captureScreenshot'); (await import('node:fs')).writeFileSync(`${sp}/gallery.png`, Buffer.from(shot2.result.data, 'base64'));
chrome.kill(); process.exit(0);
EOF
cd $SP/gtest && node drive.mjs $SP/gtest

